import{_ as a,o as r,c as l,a5 as t}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"WordPress 文章目录插件 — 侧边悬浮导航","description":"","frontmatter":{"标题":"WordPress 文章目录插件 — 侧边悬浮导航","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["TOC","WordPress","侧边栏导航","悬浮面板","文章目录","滚动高亮","目录插件","锚点跳转","阅读优化"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"标题自动扫描与层级目录树","slug":"标题自动扫描与层级目录树","link":"#标题自动扫描与层级目录树","children":[]},{"level":3,"title":"侧边栏悬浮面板","slug":"侧边栏悬浮面板","link":"#侧边栏悬浮面板","children":[]},{"level":3,"title":"滚动位置实时高亮","slug":"滚动位置实时高亮","link":"#滚动位置实时高亮","children":[]},{"level":3,"title":"平滑锚点跳转","slug":"平滑锚点跳转","link":"#平滑锚点跳转","children":[]},{"level":3,"title":"折叠与展开","slug":"折叠与展开","link":"#折叠与展开","children":[]},{"level":3,"title":"回到顶部按钮","slug":"回到顶部按钮","link":"#回到顶部按钮","children":[]},{"level":3,"title":"标题项计数","slug":"标题项计数","link":"#标题项计数","children":[]},{"level":3,"title":"手机端独立适配","slug":"手机端独立适配","link":"#手机端独立适配","children":[]},{"level":3,"title":"颜色与样式全面自定义","slug":"颜色与样式全面自定义","link":"#颜色与样式全面自定义","children":[]},{"level":3,"title":"中英双语界面","slug":"中英双语界面","link":"#中英双语界面","children":[]},{"level":3,"title":"高性能与零侵入","slug":"高性能与零侵入","link":"#高性能与零侵入","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：基础配置","slug":"第二步-基础配置","link":"#第二步-基础配置","children":[]},{"level":3,"title":"第三步：交互与辅助功能配置","slug":"第三步-交互与辅助功能配置","link":"#第三步-交互与辅助功能配置","children":[]},{"level":3,"title":"第四步：手机端与外观调整","slug":"第四步-手机端与外观调整","link":"#第四步-手机端与外观调整","children":[]},{"level":3,"title":"第五步：验证效果","slug":"第五步-验证效果","link":"#第五步-验证效果","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.1（2026-07-12）","slug":"v1-0-1-2026-07-12","link":"#v1-0-1-2026-07-12","children":[]},{"level":3,"title":"v1.0.0","slug":"v1-0-0","link":"#v1-0-0","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 文章目录插件 — 侧边悬浮导航.md","filePath":"md/wordpress主题插件/WordPress 文章目录插件 — 侧边悬浮导航.md"}'),o={name:"md/wordpress主题插件/WordPress 文章目录插件 — 侧边悬浮导航.md"};function n(i,e,h,s,d,b){return r(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="wordpress-文章目录插件-—-侧边悬浮导航" tabindex="-1">WordPress 文章目录插件 — 侧边悬浮导航 <a class="header-anchor" href="#wordpress-文章目录插件-—-侧边悬浮导航" aria-label="Permalink to &quot;WordPress 文章目录插件 — 侧边悬浮导航&quot;">​</a></h1><blockquote><p>自动提取文章中的 h1~h6 标题生成层级目录树，以侧边悬浮面板形式呈现，支持滚动位置实时高亮、平滑锚点跳转、折叠收缩、回到顶部，以及全面的颜色和尺寸自定义。</p></blockquote><p><strong>版本</strong>：v1.0.1<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：&gt;= 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-38.png" alt=""></p><p>本插件在前端自动扫描文章正文中的 h1~h6 标题，基于标题层级关系构建嵌套目录树，并通过固定悬浮面板展示在页面侧边。用户在阅读长文章时，可随时查看当前所处章节位置，点击目录项即可平滑滚动到对应标题。</p><p>插件采用纯前端 DOM 扫描方式实现，不会修改文章正文内容，也不会在数据库中存储额外数据，对网站性能无任何负面影响。</p><p>后台提供模块化卡片式设置界面，涵盖基础参数、交互行为、辅助功能、手机适配、外观样式和高级选项六大模块，所有配置项均通过滑动开关和内联参数组直观呈现，修改即时生效。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="标题自动扫描与层级目录树" tabindex="-1">标题自动扫描与层级目录树 <a class="header-anchor" href="#标题自动扫描与层级目录树" aria-label="Permalink to &quot;标题自动扫描与层级目录树&quot;">​</a></h3><p>插件在前端自动扫描文章正文区域内的 h1~h6 标题，根据标题层级自动构建嵌套目录列表。默认扫描六个层级（H1~H6），可在后台勾选需要的层级，灵活控制目录展示深度。</p><p>— 自动为无 id 的标题生成唯一锚点，确保跳转正常；<br> — 智能过滤非正文区域的标题（如评论区、推荐文章、侧边栏小工具等），避免目录内容冗余；<br> — 自动跳过空文本和过短标题，保证目录项质量。</p><h3 id="侧边栏悬浮面板" tabindex="-1">侧边栏悬浮面板 <a class="header-anchor" href="#侧边栏悬浮面板" aria-label="Permalink to &quot;侧边栏悬浮面板&quot;">​</a></h3><p>目录以固定悬浮面板形式展示在页面左侧或右侧，不占用正文布局空间，随页面滚动始终可见。</p><p>— 右侧悬浮（默认）或左侧悬浮，后台一键切换；<br> — 面板宽度可调（160px~500px），默认 240px；<br> — 距顶部距离可配置，自动叠加页面固定导航栏高度，确保目录面板不被遮挡；<br> — 面板最大高度可设固定值或自动适应视口。</p><h3 id="滚动位置实时高亮" tabindex="-1">滚动位置实时高亮 <a class="header-anchor" href="#滚动位置实时高亮" aria-label="Permalink to &quot;滚动位置实时高亮&quot;">​</a></h3><p>页面滚动时，目录中当前阅读位置对应的标题项自动高亮，左侧出现蓝色指示条，背景色同步变化。高亮颜色、背景色、边框颜色均可在后台自定义。</p><p>— 内置页面固定/粘性导航栏高度自动检测机制，动态调整激活判定的偏移量；<br> — 窗口大小变化时自动重新校准，适配响应式布局；<br> — 目录列表自动跟随高亮项滚动，确保当前项始终在可视区域内。</p><h3 id="平滑锚点跳转" tabindex="-1">平滑锚点跳转 <a class="header-anchor" href="#平滑锚点跳转" aria-label="Permalink to &quot;平滑锚点跳转&quot;">​</a></h3><p>点击任意目录项，页面平滑滚动到对应标题位置，并自动计算固定导航栏高度作为滚动偏移，确保标题不被遮挡。</p><p>— 超长页面（默认超过 2000px）自动启用分段跳转，先快速接近再精准落地，避免一次性长距离滚动带来的体验割裂；<br> — 分段次数可后台配置（1~10 次），适配不同页面长度；<br> — 滚动阈值可自定义，短页面直接平滑跳转，无需分段。</p><h3 id="折叠与展开" tabindex="-1">折叠与展开 <a class="header-anchor" href="#折叠与展开" aria-label="Permalink to &quot;折叠与展开&quot;">​</a></h3><p>目录面板支持收缩态与展开态自由切换。</p><p>— 收缩态：面板收起，仅显示竖排文字标签，最大化释放页面空间；<br> — 展开态：完整显示标题栏、目录列表和回到顶部按钮；<br> — 点击竖排标签可在收缩/展开之间切换；<br> — 支持 Hover 展开/离开收缩（鼠标悬停在标签上自动展开目录，移出自动收缩）；<br> — 支持点击正文自动收缩（点击文章内容区域时目录自动折叠）；<br> — 展开/收缩过程可启用 CSS 平滑过渡动画；<br> — 收缩状态可通过 localStorage 记忆，刷新页面后保持用户选择。</p><h3 id="回到顶部按钮" tabindex="-1">回到顶部按钮 <a class="header-anchor" href="#回到顶部按钮" aria-label="Permalink to &quot;回到顶部按钮&quot;">​</a></h3><p>目录面板底部可显示回到顶部箭头按钮，点击后平滑滚动至页面顶端，方便长文章快速返回。</p><h3 id="标题项计数" tabindex="-1">标题项计数 <a class="header-anchor" href="#标题项计数" aria-label="Permalink to &quot;标题项计数&quot;">​</a></h3><p>目录标题栏旁可显示当前文章标题总数（如”共 12 项”），帮助读者快速了解文章结构规模。</p><h3 id="手机端独立适配" tabindex="-1">手机端独立适配 <a class="header-anchor" href="#手机端独立适配" aria-label="Permalink to &quot;手机端独立适配&quot;">​</a></h3><p>插件内置手机端适配方案，小屏设备上的目录面板可独立配置。</p><p>— 手机端开关：关闭后移动设备完全不显示目录，避免干扰小屏阅读；<br> — 手机端悬浮位置独立设置（左侧或右侧）；<br> — 手机端距顶部距离独立设置，适配移动端导航栏高度；<br> — 移动端面板宽度自动缩小至 220px，字号自适应减小，确保窄屏体验。</p><h3 id="颜色与样式全面自定义" tabindex="-1">颜色与样式全面自定义 <a class="header-anchor" href="#颜色与样式全面自定义" aria-label="Permalink to &quot;颜色与样式全面自定义&quot;">​</a></h3><p>后台提供 7 种颜色配置项，覆盖目录面板的所有视觉元素，通过取色器直观选择。</p><p>— 背景颜色、标题文字颜色、目录项文字颜色；<br> — Hover 悬停颜色、高亮项颜色、高亮项背景色；<br> — 边框/分隔线颜色；<br> — 标题栏字号、目录项字号分别可调。</p><p>所有颜色和尺寸配置通过内联 CSS 动态注入，无需修改主题文件，切换主题后样式不受影响。</p><h3 id="中英双语界面" tabindex="-1">中英双语界面 <a class="header-anchor" href="#中英双语界面" aria-label="Permalink to &quot;中英双语界面&quot;">​</a></h3><p>插件后台界面支持中文、English 和自动三种语言模式。</p><p>— 自动模式根据 WordPress 站点语言自动切换，中文站点显示中文，其他站点显示英文；<br> — 语言通过独立工具栏一键切换，切换后即时生效；<br> — 所有设置项标签、描述、提示文字均完整双语覆盖。</p><h3 id="高性能与零侵入" tabindex="-1">高性能与零侵入 <a class="header-anchor" href="#高性能与零侵入" aria-label="Permalink to &quot;高性能与零侵入&quot;">​</a></h3><p>— 纯前端 DOM 扫描构建目录，不修改文章数据库、不存储额外元数据；<br> — 配置读取使用 PHP 静态缓存，单次请求仅一次数据库查询；<br> — CSS / JS 仅在文章和页面详情页按需加载，其他页面零额外开销；<br> — 全局开关关闭后完全不加载任何资源，对网站性能无影响；<br> — 停用插件时可选择是否清除所有配置数据，便于测试或迁移。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>wzml_mulu</code> 文件夹上传至网站 <code>wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「文章目录」并点击启用。</p><p>也可以直接在 WordPress 后台「插件 — 安装插件」中上传 zip 包安装。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-39.png" alt=""></p><h3 id="第二步-基础配置" tabindex="-1">第二步：基础配置 <a class="header-anchor" href="#第二步-基础配置" aria-label="Permalink to &quot;第二步：基础配置&quot;">​</a></h3><p>进入后台「文章目录」菜单，在基础设置卡片中：</p><p>— 确认启用插件开关为开启状态；<br> — 设置目录标题文字，默认为”文章目录”；<br> — 选择悬浮位置（右侧或左侧）和面板宽度；<br> — 配置正文内容容器的 CSS 选择器（多个用逗号分隔），默认已覆盖主流主题的 <code>.entry-content</code> 和 <code>.post-content</code>；<br> — 勾选需要显示在目录中的标题层级（H1~H6）。</p><h3 id="第三步-交互与辅助功能配置" tabindex="-1">第三步：交互与辅助功能配置 <a class="header-anchor" href="#第三步-交互与辅助功能配置" aria-label="Permalink to &quot;第三步：交互与辅助功能配置&quot;">​</a></h3><p>在交互设置卡片中按需开启：</p><p>— 默认展开：开启则页面加载后目录处于展开状态；<br> — 点击正文自动收缩：开启后点击文章正文区域目录自动折叠；<br> — Hover 展开/离开收缩：鼠标移入竖排标签时展开目录，移出收缩；<br> — 平滑过渡动画：展开/收缩过程启用 CSS 过渡效果；<br> — 记住收缩状态：收缩/展开状态通过 localStorage 记忆，刷新不丢失。</p><p>在辅助功能卡片中开启回到顶部按钮和标题计数。</p><h3 id="第四步-手机端与外观调整" tabindex="-1">第四步：手机端与外观调整 <a class="header-anchor" href="#第四步-手机端与外观调整" aria-label="Permalink to &quot;第四步：手机端与外观调整&quot;">​</a></h3><p>在手机端设置卡片中，可独立控制移动端是否显示目录及其位置和距顶距离。</p><p>在显示样式卡片中，可调整距顶部距离、最大高度、超长页面分段跳转阈值和次数、标题栏与目录项字号，以及 7 种颜色配置。</p><h3 id="第五步-验证效果" tabindex="-1">第五步：验证效果 <a class="header-anchor" href="#第五步-验证效果" aria-label="Permalink to &quot;第五步：验证效果&quot;">​</a></h3><p>打开任意一篇包含 h1~h6 标题的文章详情页，确认侧边出现目录悬浮面板。滚动页面验证目录高亮跟随是否正常，点击目录项验证跳转是否平滑准确。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件不修改文章正文内容，目录完全通过前端 DOM 扫描动态生成，无需担心数据安全问题；<br> — 如果目录中未出现预期的标题，请检查后台「内容区选择器」配置是否匹配当前主题的文章正文容器 CSS 选择器；<br> — 手机端默认开启，如需在小屏设备上隐藏目录，请在手机端设置卡片中关闭「手机端启用」开关；<br> — 如果目录跳转后标题被固定导航栏遮挡，可在后台调整「距顶部距离」参数，或依赖插件内置的固定导航栏自动检测功能（已默认开启）；<br> — 更换主题后，建议检查「内容区选择器」是否需要更新为新主题的正文容器选择器；<br> — 目录面板的 z-index 为 9999，如遇特殊主题有更高层级的元素遮挡，可在 CSS 中覆盖该值。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.top<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-1-2026-07-12" tabindex="-1">v1.0.1（2026-07-12） <a class="header-anchor" href="#v1-0-1-2026-07-12" aria-label="Permalink to &quot;v1.0.1（2026-07-12）&quot;">​</a></h3><p>— 新增中英双语后台界面，支持中文/English/自动三种语言模式，通过独立工具栏一键切换；<br> — 后台界面全面重构为模块化卡片布局，包含六大设置模块，滑动开关与内联参数组直观呈现；<br> — 集成 WordPress Settings API，配置存取与安全校验规范化；<br> — 新增 PHP 静态缓存机制，优化配置读取性能，单次请求仅一次数据库查询；<br> — 新增停用插件时清除配置数据选项，便于测试和迁移；<br> — 新增 uninstall.php 卸载清理脚本。</p><h3 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h3><p>— 首次发布，实现文章标题自动扫描与层级目录树构建；<br> — 侧边栏悬浮面板，支持左右位置切换；<br> — 滚动位置实时高亮当前章节；<br> — 平滑锚点跳转，超长页面自动分段跳转；<br> — 折叠/展开交互，收缩态显示竖排标签；<br> — 回到顶部按钮和标题计数辅助功能；<br> — 手机端独立适配，包含开关和位置参数；<br> — 7 种颜色 + 字号 + 尺寸全面自定义。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3071.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3071.html</a></p>',68)])])}const u=a(o,[["render",n]]);export{c as __pageData,u as default};
